package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.util.OwnerIdentities;

/**
 * Stamps the deterministic {@code householdId} onto the freshly built {@link Owner}.
 *
 * <p>The identifier is computed from the owner's own last name and postcode alone (see
 * {@link OwnerIdentities#householdId(Owner)}) — the first 12 hex characters of SHA-256 over
 * {@code normalizedLastName + "|" + postcode}. It is therefore assigned to <em>every</em> owner,
 * not only those that declared {@code sharesHousehold}: owners with the same last name and postcode
 * compute the same value and share a household automatically, with no scan of existing owners and no
 * back-filling.
 *
 * <p>Runs after {@link BuildOwner} (which produces the new {@link Owner}) and before the checks that
 * key off the household — {@link CheckUniqueIdentity} (the household-duplicate block) and
 * {@link CheckPossibleDuplicate} — so the household is fixed before it is consulted.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(OwnerIdentities.householdId(owner));
    }
}
===== CheckUniqueIdentity.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * Rejects a create-owner request that would land in a household that already exists. The household
 * is keyed on {@code (lastName, postcode)} through the deterministic {@code householdId} assigned by
 * {@link AssignHousehold}, so a second owner sharing an existing owner's last name and postcode is a
 * household duplicate and is rejected with 409 (see {@link DuplicateIdentityException}).
 *
 * <p>A request may opt in with {@code sharesHousehold=true} to declare that it intentionally joins
 * that household. Doing so <em>bypasses this block</em> — the owner is created as a declared
 * household member — so {@code sharesHousehold} now only lifts the duplicate rejection rather than
 * creating the link (the link is implicit in the shared {@code householdId}).
 *
 * <p>Runs after {@link BuildOwner} and {@link AssignHousehold} so the new owner's {@code householdId}
 * is already assigned, and before {@link SaveOwner} so the new owner is not compared against itself.
 */
public class CheckUniqueIdentity {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // declared household member: bypass the duplicate block.
        }
        String householdId = owner.getHouseholdId();
        if (householdId == null || householdId.isBlank()) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
                continue; // never collide with self (should not yet be persisted, but be safe)
            }
            if (householdId.equals(existing.getHouseholdId())) {
                throw new DuplicateIdentityException(householdId);
            }
        }
    }
}
===== CheckPossibleDuplicate.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Flags the freshly built {@link Owner} as a soft (non-blocking) duplicate before it is saved.
 * A soft duplicate is one that is <em>not</em> a hard duplicate (an exact {@code identityKey}
 * match, already rejected with 409 by {@link CheckUniqueIdentity}) but that shares an existing
 * owner's {@code lastName} and {@code postcode} while having a <em>different</em> telephone.
 *
 * <p>When such an existing owner is found the new owner is still created, with
 * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
 * owner's id (the earliest such owner when several match); otherwise {@code possibleDuplicate} is
 * {@code false} and {@code possibleDuplicateOf} is left unset.
 *
 * <p>Runs after {@link CheckUniqueIdentity} (so hard duplicates are already out) and before
 * {@link SaveOwner} (so the new owner is not compared against itself).
 *
 * <p>An owner that declared {@code sharesHousehold=true} is an intentional household member, not a
 * suspected duplicate, so it is never flagged: {@code possibleDuplicate} is left {@code false}.
 */
public class CheckPossibleDuplicate {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            owner.setPossibleDuplicate(false);
            owner.setPossibleDuplicateOf(null);
            return; // a declared household member is not a suspected duplicate.
        }
        String lastName = normalize(owner.getLastName());
        String postcode = normalize(owner.getPostcode());
        String telephone = normalizeTelephone(owner.getTelephone());

        Integer matchId = null;
        if (!lastName.isEmpty() && !postcode.isEmpty()) {
            for (Owner existing : ownerRepository.findAll()) {
                if (owner.getId() != null && owner.getId().equals(existing.getId())) {
                    continue; // never match self
                }
                if (lastName.equals(normalize(existing.getLastName()))
                        && postcode.equals(normalize(existing.getPostcode()))
                        && !telephone.equals(normalizeTelephone(existing.getTelephone()))) {
                    if (matchId == null || existing.getId() < matchId) {
                        matchId = existing.getId();
                    }
                }
            }
        }

        owner.setPossibleDuplicate(matchId != null);
        owner.setPossibleDuplicateOf(matchId);
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
    }

    private static String normalizeTelephone(String telephone) {
        try {
            return OwnerTelephone.toE164(telephone);
        }
        catch (InvalidTelephoneException ex) {
            // A value that cannot form a valid E.164 number is represented by its raw form
            // (or empty when absent) so the comparison stays total.
            return telephone == null ? "" : telephone.trim();
        }
    }
}
