package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.util.OwnerIdentities;

/**
 * Assigns the {@code customerCode} to the freshly built {@link Owner} before it is saved.
 *
 * <p>The code is formatted {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the
 * owner's postcode (falling back to city — see
 * {@link org.springframework.samples.petclinic.util.Localities}), and HASH8 is the first 8
 * upper-case hex characters of SHA-256 over {@code normalizedTelephone + lastName}
 * (e.g. {@code 'NSW-1A2B3C4D'}). The code no longer carries a per-city sequence number, so it is a
 * pure function of the owner's region and identity and does not depend on other owners.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner) {
        owner.setCustomerCode(OwnerIdentities.customerCode(owner));
    }
}
===== AssignMembershipNumber.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the {@code membershipNumber} to the freshly built {@link Owner} before it is saved.
 *
 * <p>The number is formatted {@code '<customerCode>-M<YY>'}, where {@code customerCode} is the
 * code assigned by {@link AssignCustomerCode} and YY is the last two digits of the owner's
 * {@code registrationDate} year (the effective, business-day-adjusted date resolved by
 * {@link ResolveRegistrationDate} and stored by {@link BuildOwner}),
 * e.g. {@code 'NSW-1A2B3C4D-M26'}. This step therefore runs after both are set.
 */
public class AssignMembershipNumber {

    public void service(@Val Owner owner) {
        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
    }
}
===== CountNamesakes.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records the {@code namesakeCount} on the freshly built {@link Owner} before it is saved:
 * the number of existing owners that share the same first and last name, compared
 * case-insensitively.
 *
 * <p>Runs before {@link SaveOwner} so the new owner is not yet counted — the count reflects
 * only owners that existed before this create.
 */
public class CountNamesakes {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = normalize(owner.getFirstName());
        String lastName = normalize(owner.getLastName());
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (firstName.equals(normalize(existing.getFirstName()))
                    && lastName.equals(normalize(existing.getLastName()))) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }

    private static String normalize(String value) {
        return value == null ? "" : value.toLowerCase();
    }
}
